<?php
declare(strict_types=1);
const AZ_STATUSES=['placed','confirmed','dispatched','delivered','cancelled','returned'];
const AZ_PAYMENTS=['cod'=>'Cash on delivery','bank'=>'Bank transfer','wallet'=>'JazzCash / Easypaisa'];
function az_sum(array $list,callable $fn): int|float { return array_sum(array_map($fn,$list)); }
function az_rate($n,$d): ?float { return $d?round($n/$d*100,1):null; }
function az_day(?int $time=null): string { return gmdate('Y-m-d',($time??time())+18000); }
function az_days($raw): ?int { if($raw===null||$raw===''||$raw==='all') return null; $n=(int)$raw; return $n>=1&&$n<=3650?$n:30; }
function az_dayadd(string $key,int $days): string { return gmdate('Y-m-d',strtotime($key.'T00:00:00Z')+$days*86400); }
function az_start(?int $days): ?string { return $days?az_dayadd(az_day(),1-$days):null; }
function az_range(array $o,?string $start): bool { $t=az_time($o['createdAt']??null); return $t>0&&(!$start||az_day($t)>=$start); }
function az_outcome(array $orders): array { $d=count(array_filter($orders,fn($o)=>$o['status']==='delivered')); $r=count(array_filter($orders,fn($o)=>$o['status']==='returned')); return ['delivered'=>$d,'returned'=>$r,'rate'=>az_rate($r,$d+$r)]; }
function az_kept(array $orders): array { return array_values(array_filter($orders,fn($o)=>!in_array($o['status'],['cancelled','returned']))); }
function az_insights(?int $days): array {
    $all=array_values(array_filter(az_db('orders'),fn($o)=>az_time($o['createdAt']??null)>0)); $start=az_start($days); $orders=array_values(array_filter($all,fn($o)=>az_range($o,$start))); $kept=az_kept($orders); $live=array_values(array_filter($orders,fn($o)=>$o['status']!=='cancelled')); $byStatus=[];
    foreach(AZ_STATUSES as $st) $byStatus[$st]=count(array_filter($orders,fn($o)=>$o['status']===$st));
    $revenue=array_sum(array_column($kept,'total')); $payment=[];
    foreach(AZ_PAYMENTS as $key=>$label) { $list=array_values(array_filter($orders,fn($o)=>$o['payment']===$key)); $payment[]=['key'=>$key,'label'=>$label,'orders'=>count($list),'share'=>az_rate(count($list),count($orders)),'revenue'=>array_sum(array_column(az_kept($list),'total')),'refusal'=>az_outcome($list)]; }
    $today=az_day(); $first=$start?:($all?az_day(min(array_map(fn($o)=>az_time($o['createdAt']),$all))):$today); $span=(int)round((strtotime($today)-strtotime($first))/86400)+1; $bucket=$span>120?'week':'day'; $series=[];
    $week=fn($k)=>az_dayadd($k,-((int)gmdate('N',strtotime($k.'T00:00:00Z'))-1));
    if($orders||$days) { for($k=$bucket==='week'?$week($first):$first;$k<=$today;$k=az_dayadd($k,$bucket==='week'?7:1)) $series[$k]=['date'=>$k,'revenue'=>0,'orders'=>0,'dropped'=>0]; foreach($orders as $o) { $key=az_day(az_time($o['createdAt'])); if($bucket==='week') $key=$week($key); if(!isset($series[$key])) continue; if(in_array($o['status'],['cancelled','returned'])) $series[$key]['dropped']++; else { $series[$key]['revenue']+=$o['total']; $series[$key]['orders']++; } } }
    $prod=[]; foreach($kept as $o) foreach($o['items'] as $i) { $id=$i['id']; $prod[$id]??=['id'=>$id,'title'=>$i['title'],'qty'=>0,'sales'=>0,'orders'=>[]]; $prod[$id]['qty']+=$i['qty']; $prod[$id]['sales']+=$i['line']; $prod[$id]['orders'][$o['id']]=true; } $top=array_values($prod); usort($top,fn($a,$b)=>($b['qty']<=>$a['qty'])?:($b['sales']<=>$a['sales'])); $top=array_map(function($p){ $p['orders']=count($p['orders']); return $p; },array_slice($top,0,10));
    $cityMap=[]; foreach($orders as $o) $cityMap[trim($o['customer']['city']??'')?:'Unknown'][]=$o; $cities=[];
    foreach($cityMap as $city=>$list) $cities[]=array_merge(['city'=>$city,'orders'=>count($list),'revenue'=>array_sum(array_column(az_kept($list),'total')),'cancelled'=>count(array_filter($list,fn($o)=>$o['status']==='cancelled'))],az_outcome($list)); usort($cities,fn($a,$b)=>($b['orders']<=>$a['orders'])?:($b['revenue']<=>$a['revenue']));
    $codes=[]; foreach($live as $o) if(!empty($o['coupon'])) { $key=$o['coupon']; $codes[$key]??=['code'=>$key,'uses'=>0,'discount'=>0,'total'=>0,'freeDelivery'=>0]; $disc=array_filter($o['discounts'],fn($d)=>$d['key']==='coupon'); $codes[$key]['uses']++; $codes[$key]['discount']+=array_sum(array_column($disc,'amount')); $codes[$key]['total']+=$o['total']; if(!$disc) $codes[$key]['freeDelivery']++; } $codes=array_values($codes); usort($codes,fn($a,$b)=>($b['uses']<=>$a['uses'])?:($b['discount']<=>$a['discount']));
    $history=[]; $ordered=$all; usort($ordered,fn($a,$b)=>strcmp($a['createdAt'],$b['createdAt'])); foreach($ordered as $o) if($o['status']!=='cancelled'&&!empty($o['customer']['phone'])) $history[$o['customer']['phone']][]=$o;
    $phones=array_unique(array_filter(array_column(array_column($live,'customer'),'phone'))); $fresh=0; $cameBack=0; $returning=0;
    foreach($phones as $phone) { $h=$history[$phone]??[]; if($h&&az_range($h[0],$start)) { $fresh++; if(count($h)>1) $cameBack++; } else $returning++; }
    $repeat=count(array_filter($live,fn($o)=>($history[$o['customer']['phone']][0]['id']??null)!==$o['id'])); $prepaid=az_sum(array_filter($payment,fn($p)=>$p['key']!=='cod'),fn($p)=>$p['orders']);
    return ['days'=>$days,'from'=>$start,'to'=>$today,'bucket'=>$bucket,'totalOrdersEver'=>count($all),'orders'=>['placed'=>count($orders),'kept'=>count($kept),'byStatus'=>$byStatus],'revenue'=>$revenue,'deliveredRevenue'=>array_sum(array_column(array_filter($kept,fn($o)=>$o['status']==='delivered'),'total')),'aov'=>$kept?(int)round($revenue/count($kept)):0,'items'=>az_sum($kept,fn($o)=>array_sum(array_column($o['items'],'qty'))),'discounts'=>az_sum($kept,fn($o)=>array_sum(array_column($o['discounts'],'amount'))),'credits'=>az_sum($kept,fn($o)=>array_sum(array_column($o['credits']??[],'amount'))),'payment'=>$payment,'prepaid'=>['orders'=>$prepaid,'share'=>az_rate($prepaid,count($orders))],'refusal'=>az_outcome($orders),'cancelRate'=>az_rate($byStatus['cancelled'],count($orders)),'series'=>array_values($series),'topProducts'=>$top,'cities'=>array_slice($cities,0,10),'cityCount'=>count($cities),'coupons'=>$codes,'customers'=>['total'=>count($phones),'new'=>$fresh,'cameBack'=>$cameBack,'returning'=>$returning,'repeatOrders'=>$repeat,'orders'=>count($live),'repeatShare'=>az_rate($repeat,count($live))]];
}
function az_validate_coupon(array $b,?array $prev=null): array {
    $bad=function($field,$error){ az_json(422,['field'=>$field,'error'=>$error]); }; $s=az_store(); $code=$prev['code']??strtoupper(trim((string)($b['code']??'')));
    if(!$prev) { if(str_starts_with($code,'AZP')) $bad('code','AZP codes are reserved for creator partnerships.'); if(!preg_match('/^[A-Z0-9]{3,20}$/',$code)) $bad('code','Use 3 to 20 letters (A–Z) and numbers, no spaces.'); if(isset($s['coupons'][$code])||$code===($s['launchOffer']['code']??'')) $bad('code','This code is already in data/store.json. Pick another one.'); if(az_find(az_db('coupons'),fn($c)=>$c['code']===$code)) $bad('code','This code already exists. Edit it in the list below.'); }
    $type=(string)($b['type']??''); if(!in_array($type,['percent','fixed','freeship'])) $bad('type','Choose percent, fixed or free delivery.'); $value=$type==='freeship'?null:($b['value']??null);
    if($type!=='freeship'&&(!is_numeric($value)||(float)$value!==(float)(int)$value||(int)$value<($type==='percent'?1:10)||(int)$value>($type==='percent'?90:50000))) $bad('value',$type==='percent'?'Percent off must be a whole number from 1 to 90.':'Rupees off must be a whole number from 10 to 50,000.');
    $min=empty($b['minSubtotal'])?null:$b['minSubtotal']; if($min!==null&&($type==='freeship'||!is_numeric($min)||(float)$min!==(float)(int)$min||$min<1||$min>500000||($type==='fixed'&&$min<$value))) $bad('minSubtotal','Please enter a valid minimum spend at least as large as the discount.');
    $expiry=trim((string)($b['expiresOn']??''))?:null; if($expiry&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$expiry)||gmdate('Y-m-d',strtotime($expiry.'T00:00:00Z')?:0)!==$expiry||(!$prev&&$expiry<az_day()))) $bad('expiresOn','Pick a valid expiry date that is not in the past.');
    $max=empty($b['maxUses'])?null:$b['maxUses']; if($max!==null&&(!is_numeric($max)||(float)$max!==(float)(int)$max||$max<1||$max>1000000)) $bad('maxUses','Max uses must be a whole number, or empty for no limit.');
    return ['code'=>$code,'type'=>$type,'value'=>$value!==null?(int)$value:null,'label'=>az_clean($b['label']??'',60),'minSubtotal'=>$min!==null?(int)$min:null,'expiresOn'=>$expiry,'maxUses'=>$max!==null?(int)$max:null,'firstOrderOnly'=>!empty($b['firstOrderOnly'])];
}
function az_coupon_list(): array {
    $s=az_store(); $codes=array_map(fn($c)=>array_merge($c,['label'=>$c['label']?:az_coupon_label($c),'uses'=>az_coupon_uses($c['code']),'state'=>az_coupon_state($c)]),array_reverse(az_db('coupons'))); $storeCodes=[];
    foreach($s['coupons']??[] as $code=>$c) $storeCodes[]=['code'=>$code,'type'=>$c['type'],'value'=>$c['value']??null,'label'=>$c['label']??'','minSubtotal'=>$c['minSubtotal']??null,'firstOrderOnly'=>!empty($c['firstOrderOnly']),'uses'=>az_coupon_uses($code),'endsAt'=>$code===($s['launchOffer']['code']??'')?$s['launchOffer']['endsAt']:null,'ended'=>$code===($s['launchOffer']['code']??'')&&time()>az_time($s['launchOffer']['endsAt'])];
    return ['codes'=>$codes,'storeCodes'=>$storeCodes];
}
function az_csv(array $rows,string $name): never {
    $out="\xEF\xBB\xBF"; foreach($rows as $row) { $cells=[]; foreach($row as $v) { $numeric=is_int($v)||is_float($v); $s=(string)($v??''); if(!$numeric&&preg_match('/^[=+\-@\t\r]/',$s)) $s="'".$s; $cells[]=preg_match('/[",\r\n]|^\s|\s$/',$s)?'"'.str_replace('"','""',$s).'"':$s; } $out.=implode(',',$cells)."\r\n"; }
    header('Content-Disposition: attachment; filename="'.$name.'-'.az_day().'.csv"'); header('Cache-Control: no-store'); az_text(200,$out,'text/csv; charset=utf-8');
}
function az_item_text(array $i): string { return $i['title'].' ('.$i['size'].') x'.$i['qty'].(!empty($i['addons'])?' + '.implode(', ',array_column($i['addons'],'label')):''); }
function az_admin_api(string $p,string $method,array $b): void {
    if(!str_starts_with($p,'/api/admin/')) return;
    if($p==='/api/admin/catalog'&&$method==='GET') az_json(200,array_values(array_filter(az_catalog(),fn($product)=>empty($product['unlisted']))));
    if($p==='/api/admin/summary'&&$method==='GET') {
        $orders=az_db('orders'); $live=array_filter($orders,fn($o)=>$o['status']!=='cancelled'); $accounts=az_db('accounts'); $cards=array_filter(az_db('giftcards'),fn($c)=>az_gift_status($c)==='active'); $products=az_public_catalog()['products'];
        az_json(200,['orders'=>count($orders),'revenue'=>array_sum(array_column($live,'total')),'pending'=>count(array_filter($orders,fn($o)=>in_array($o['status'],['placed','confirmed']))),'waitlist'=>count(az_db('waitlist')),'newsletter'=>count(az_db('newsletter')),'leads'=>count(az_db('leads')),'products'=>count($products),'members'=>count($accounts),'pointsOutstanding'=>array_sum(array_column($accounts,'points')),'giftcardsOutstanding'=>array_sum(array_column($cards,'balance')),'giftcardsToSend'=>count(array_filter($cards,fn($c)=>empty($c['sentAt']))),'restockWaiting'=>count(array_filter(az_db('restock'),fn($r)=>$r['status']==='pending')),'abandonedBags'=>count(array_filter(az_drafts(),fn($d)=>empty($d['recovered'])&&az_time($d['updatedAt'])<time()-1800)),'couponsActive'=>count(array_filter(az_db('coupons'),fn($c)=>az_coupon_state($c)==='active')),'confirmedToBook'=>count(array_filter($orders,fn($o)=>$o['status']==='confirmed'&&(bool)az_find($o['items'],fn($i)=>empty($i['meta']['digital'])))),'notifications'=>['email'=>az_mail_enabled(),'telegram'=>az_telegram_enabled()],'lowStock'=>array_values(array_map(fn($p)=>array_intersect_key($p,array_flip(['id','title','stock'])),array_filter($products,fn($p)=>(bool)array_filter($p['stock'],fn($q)=>$q<=3))))]);
    }
    if($p==='/api/admin/orders'&&$method==='GET') az_json(200,array_reverse(az_db('orders')));
    if(preg_match('~^/api/admin/orders/([A-Z0-9]+)$~',$p,$m)&&$method==='PATCH') {
        $orders=az_db('orders'); $i=az_index($orders,fn($o)=>$o['id']===$m[1]); if($i===null) az_fail(404,'No such order'); $o=$orders[$i]; $status=$b['status']??$o['status']; if(!in_array($status,AZ_STATUSES,true)) az_fail(400,'Bad status');
        foreach(['courier'=>40,'tracking'=>60,'adminNote'=>500] as $k=>$n) if(array_key_exists($k,$b)) $o[$k]=az_clean($b[$k],$n)?:null;
        if(in_array($status,['cancelled','returned'])&&!in_array($o['status'],['cancelled','returned'])) foreach($o['items'] as $line) { $product=az_catalog()[$line['id']]??null; if($product) az_stock($line['id'],$line['size'],($product['stock'][$line['size']]??0)+$line['qty']); }
        $prev=$o['status']; $o['status']=$status; if($prev!==$status) $o['history'][]=['status'=>$status,'at'=>az_now()]; $orders[$i]=$o; az_set('orders',$orders); az_status_changed($o,$prev); az_json(200,$o);
    }
    if($p==='/api/admin/stock'&&$method==='POST') { $id=(string)($b['id']??''); $size=(string)($b['size']??''); $product=az_catalog()[$id]??null; if(!$product) az_fail(404,'No such product'); if(!in_array($size,$product['sizes'],true)||!is_numeric($b['qty']??null)) az_fail(400,'Choose a valid size and stock quantity.'); az_stock($id,$size,$b['qty']); az_json(200,['ok'=>true,'stock'=>az_catalog()[$id]['stock']]); }
    if(preg_match('~^/api/admin/(waitlist|newsletter|messages|leads)$~',$p,$m)&&$method==='GET') az_json(200,array_reverse(az_db($m[1])));
    if($p==='/api/admin/insights'&&$method==='GET') az_json(200,az_insights(az_days($_GET['days']??null)));
    if($p==='/api/admin/coupons'&&$method==='GET') az_json(200,az_coupon_list());
    if($p==='/api/admin/coupons'&&$method==='POST') { $c=array_merge(az_validate_coupon($b),['active'=>true,'createdAt'=>az_now(),'updatedAt'=>az_now()]); az_push('coupons',$c); az_json(201,$c); }
    if(preg_match('~^/api/admin/coupons/([A-Za-z0-9]{1,20})$~',$p,$m)&&$method==='PATCH') { $list=az_db('coupons'); $i=az_index($list,fn($c)=>$c['code']===strtoupper($m[1])); if($i===null) az_fail(404,'No such code'); if(!(count($b)===1&&isset($b['active'])&&is_bool($b['active']))) $list[$i]=array_merge($list[$i],az_validate_coupon($b,$list[$i])); if(isset($b['active'])&&is_bool($b['active'])) $list[$i]['active']=$b['active']; $list[$i]['updatedAt']=az_now(); az_set('coupons',$list); az_json(200,$list[$i]); }
    if($p==='/api/admin/export/orders.csv'&&$method==='GET') {
        $status=$_GET['status']??''; if($status&&$status!=='all'&&!in_array($status,AZ_STATUSES,true)) az_fail(400,'Bad status'); $days=az_days($_GET['days']??null); $list=array_values(array_filter(az_db('orders'),fn($o)=>az_range($o,az_start($days))&&(!$status||$status==='all'||$o['status']===$status))); usort($list,fn($a,$b)=>strcmp($a['createdAt'],$b['createdAt']));
        $rows=[['id','date','status','name','phone','email','city','address','items','qty','subtotal','discounts','credits','delivery','total','payment','courier','tracking']]; foreach($list as $o) { $c=$o['customer']; $local=preg_replace('/^92/','0',$c['phone']); $rows[]=[$o['id'],gmdate('Y-m-d H:i',az_time($o['createdAt'])+18000),$o['status'],$c['name'],substr($local,0,4).' '.substr($local,4),$c['email']??'',$c['city'],$c['address'],implode('; ',array_map('az_item_text',$o['items'])),array_sum(array_column($o['items'],'qty')),$o['subtotal'],array_sum(array_column($o['discounts'],'amount')),array_sum(array_column($o['credits']??[],'amount')),$o['shipping'],$o['total'],AZ_PAYMENTS[$o['payment']]??$o['payment'],$o['courier']??'',$o['tracking']??'']; } az_csv($rows,'aarzu-orders'.($status&&$status!=='all'?'-'.$status:'').($days?'-'.$days.'d':''));
    }
    if($p==='/api/admin/export/courier.csv'&&$method==='GET') { $rows=[['consignee name','phone','address','city','COD amount','item description','pieces','order ref']]; foreach(az_db('orders') as $o) if($o['status']==='confirmed'&&($items=array_values(array_filter($o['items'],fn($i)=>empty($i['meta']['digital']))))) { $c=$o['customer']; $rows[]=[$c['name'],preg_replace('/^92/','0',$c['phone']),$c['address'],$c['city'],$o['payment']==='cod'?$o['total']:0,substr(implode('; ',array_map('az_item_text',$items)),0,250),array_sum(array_column($items,'qty')),$o['id']]; } az_csv($rows,'aarzu-courier-booking'); }
}
